/** Opening the app syncs the plan: missing days are generated by the backend and appear on screen. */
import React from 'react';
import { format } from 'date-fns';
import { render, screen, waitFor } from '@testing-library/react-native';
import Home from '@/app/(tabs)/index';
import { auth } from '@/lib/firebase';
import { fakeFirestore } from '../../test/fake-firestore';

const UID = 'u1';
const today = format(new Date(), 'yyyy-MM-dd');

jest.mock('@/hooks/use-auth', () => {
  const value = {
    user: { uid: 'u1', email: 'sam@example.com' },
    profile: { uid: 'u1', displayName: 'Sam Rider', wizardCompleted: true, scheduleDaysAhead: 1 },
    loading: false,
  };
  return { useAuth: () => value };
});

beforeEach(() => {
  (auth as any).currentUser = { uid: UID, getIdToken: jest.fn().mockResolvedValue('tok') };
  fakeFirestore.seed('users', UID, { uid: UID, wizardCompleted: true });
  // The fake backend writes today's double day, as generate_training_session would.
  globalThis.fetch = jest.fn().mockImplementation(async (_url: string, init: RequestInit) => {
    const { date } = JSON.parse(String(init.body));
    fakeFirestore.serverWrite('workouts', `plan_${UID}_${date}`, {
      userId: UID, date, sport: 'cycling', name: 'Sweet Spot Ride', tss: 80, time: 5400, slot: 'am', completed: false,
    });
    fakeFirestore.serverWrite('workouts', `plan_${UID}_${date}_pm`, {
      userId: UID, date, sport: 'running', name: 'Recovery Jog', tss: 20, time: 1800, slot: 'pm', completed: false,
    });
    return { ok: true, status: 200, json: async () => ({ generated_dates: [date] }) };
  });
});

it("generates today's missing plan on open and shows it", async () => {
  await render(<Home />);
  expect(screen.getByText('Good morning, Sam')).toBeTruthy();

  expect(await screen.findByText('Sweet Spot Ride')).toBeTruthy();
  expect(screen.getByText('Recovery Jog')).toBeTruthy();

  expect(globalThis.fetch).toHaveBeenCalledTimes(1);
  const [url, init] = (globalThis.fetch as jest.Mock).mock.calls[0];
  expect(url).toMatch(/\/generate_training_session$/);
  expect(JSON.parse(init.body)).toEqual({ date: today });
  expect(init.headers.Authorization).toBe('Bearer tok');
});

it('does not regenerate a day that is already planned', async () => {
  fakeFirestore.seed('workouts', 'planned', { userId: UID, date: today, sport: 'swimming', name: 'Technique Swim', completed: false });
  await render(<Home />);
  expect(await screen.findByText('Technique Swim')).toBeTruthy();
  await waitFor(() => expect(globalThis.fetch).not.toHaveBeenCalled());
});

it('still renders when the backend is unreachable', async () => {
  jest.spyOn(console, 'error').mockImplementation(() => {});
  (globalThis.fetch as jest.Mock).mockReset().mockRejectedValue(new TypeError('Network request failed'));
  await render(<Home />);
  await waitFor(() => expect(globalThis.fetch).toHaveBeenCalled());
  expect(await screen.findByText('No workouts scheduled for today.')).toBeTruthy();
});
